    'RegisterSimpleRisk'=>'Zarejestrować SimpleRisk',
    'RegistrationText'=>'Zarejestrowane instancje SimpleRisk uzyskują natychmiastowy dostęp do dodatków Upgrade and Secure Controls Framework (SCF). Upgrade Extra zapewnia możliwość tworzenia kopii zapasowych i aktualizacji instancji SimpleRisk za pomocą kliknięcia przycisku. Secure Controls Framework (SCF) Extra zapewnia wspólną strukturę kontroli, która jest zintegrowana z funkcjonalnością SimpleRisk Governance. Po zarejestrowaniu SimpleRisk Twoje dane rejestracyjne zostaną przesłane na serwer obsługiwany przez SimpleRisk. Podane informacje rejestracyjne będą wykorzystywane przez SimpleRisk do powiadamiania klientów o nowych wersjach i aktualizacjach zabezpieczeń. Rejestracja SimpleRisk oznacza zgodę na otrzymywanie naszych wiadomości marketingowych, ale możesz zrezygnować w dowolnym momencie, korzystając z łącza rezygnacji z subskrypcji w tych wiadomościach. SimpleRisk szanuje prywatność naszych klientów, a informacje przekazane nam w procesie rejestracji SimpleRisk nigdy nie zostaną sprzedane stronom trzecim.',
